// Gezaehlt werden die Tickets selbst - kein separater Zaehler, der
// auseinanderlaufen koennte. Erkennbar sind sie an creator.type "extern",
// das Anlegedatum steckt als Zeitstempel in der id.
const TAGESLIMIT = 10;

const roh = $json.data ?? $json;
const alleTickets = (roh && typeof roh === 'object') ? Object.values(roh) : [];

const tagesbeginn = new Date();
tagesbeginn.setHours(0, 0, 0, 0);
const grenze = tagesbeginn.getTime();

const heuteSchon = alleTickets.filter((t) =>
  t && typeof t === 'object' &&
  t.creator && t.creator.type === 'extern' &&
  Number(t.id) >= grenze
).length;

const mails = $('Mail aufbereiten').all();

// Jede wartende Mail belegt einen Platz. Position i bekommt Platz
// heuteSchon + i - dadurch greift das Limit auch bei mehreren Mails
// im selben Durchlauf korrekt.
const ergebnisse = [];
for (let i = 0; i < mails.length; i++) {
  if (heuteSchon + i >= TAGESLIMIT) continue;
  ergebnisse.push({ json: { ...mails[i].json, platzNr: heuteSchon + i + 1 } });
}
return ergebnisse;

