  t && typeof t === 'object' &&
  t.creator && t.creator.type === 'extern' &&
  Number(t.id) >= grenze
).length;

const mails = $('Mail aufbereiten').all();

// Gegenstueck: alles, was ueber dem Tageslimit liegt.
const ergebnisse = [];
for (let i = 0; i < mails.length; i++) {
  if (heuteSchon + i < TAGESLIMIT) continue;
  ergebnisse.push({ json: { ...mails[i].json, heuteSchon, limit: TAGESLIMIT } });
}
return ergebnisse;

// Hinweis auf das erreichte Tageslimit.
const eigenesPostfach = String($env.JOIN_MAIL_USER || '').toLowerCase();
const ergebnisse = [];
for (const item of items) {
  const an = String(item.json.absenderMail || '').toLowerCase();
  if (!an || an === eigenesPostfach) continue;   // Schutz vor Endlosschleife
  ergebnisse.push({ json: {
    an,
    betreff: 'Tageslimit erreicht - Ihre Anfrage kam an',
    text: [
      'Hallo,',
      '',
      `fuer heute ist das Limit von ${item.json.limit} automatisch erstellten`,
      'Anfragen erreicht. Ihre Nachricht ist bei uns angekommen, es wurde aber',
      'noch kein Ticket daraus erzeugt.',
      '',
      'Das Limit schuetzt vor unerwartet hohen Kosten der KI-Auswertung.',
      'Bitte schicken Sie Ihre Anfrage morgen noch einmal - oder warten Sie',
      'kurz ab, jemand aus dem Team sieht die Nachricht ohnehin.',
      '',
      'Hinweis: Diese Nachricht wurde automatisch erzeugt.',
    ].join('\n')
  }});
}
return ergebnisse;

